import{VoxelPart}from'./voxels.js?v=balance-8';
import{buildMissile}from'./ordnance.js?v=balance-8';
const B=globalThis.BABYLON;
export const EXTRA_SPECS={
 swift:{name:'Meridian T–9',description:'Twin turboprops. Long-range wings.<br>Fast, composed, and ready for the middle ground.',mass:2300,area:23,cl0:.18,cla:4.5,clmax:1.45,cd:.027,k:.055,thrust:13500,power:2350000,stall:38,cruise:125,gearHeight:2.05,roll:1.45,pitch:.56,yaw:.36,span:15.8,noseLength:5.0,tailLength:5.45,fuelIdle:.35,fuelRate:1.50,spool:.6,pitchLimit:160,afterburner:false,cockpit:[0,1.4,2.2]},
 ufo:{name:'Astra Ω–1',description:'An alien flight machine, straight from the hangar.<br>Gravitic lift. Instant response. Ion propulsion.',mass:1800,area:24,cl0:.035,cla:2.2,clmax:1.1,cd:.012,k:.024,thrust:34000,power:0,stall:10,cruise:340,gearHeight:1.81,roll:2.4,pitch:1.05,yaw:.85,span:13.6,noseLength:6.8,tailLength:6.8,fuelIdle:.60,fuelRate:2.40,spool:.22,pitchLimit:230,afterburner:true,hover:true,cockpit:[0,1.2,2.0]}
};
export function buildExtraEquipment(scene,type,choice,parent=null){const saucer=type==='ufo',L=Math.max(0,choice.level||0),bm=!!choice.module,slot=choice.slot,root=parent||new B.TransformNode('fleet part inspection',scene),parts=[],surfaces={ailerons:[],flaps:[],elevators:[],rudders:[],props:[]},emitters=[];
 const title=choice.module?.name||((L?'Mk '+L:'Stock')+' '+slot),body=bm?(saucer?'#201027':'#16243b'):(saucer?'#c2d3d9':'#dde8e5'),edge=bm?(saucer?'#fc70dd':'#ffbd53'):(saucer?'#7ceef5':['#3e7a9e','#4a91bc','#5bbabc','#d3b354','#e3a374','#e1d89e'][L]),hot=saucer?'#b4fbff':'#ffedbb',metal=saucer?'#344457':'#4b6475';
 const add=(name,origin=[0,0,0],size=.06)=>{const p=new VoxelPart(title+' · '+name,scene,root,size,origin);p.equipmentSlot=slot;parts.push(p);return p;};
 const finish=p=>{const light=[...p.cells.values()].filter(c=>c.color===edge||c.color===hot);if(light.length&&(bm||saucer)){scene.moduleGlowMaterials??=new Map();if(!scene.moduleGlowMaterials.has(edge)){const m=scene.voxelMaterial.clone('radiant '+edge);m.emissiveColor=B.Color3.FromHexString(edge).scale(.65);scene.moduleGlowMaterials.set(edge,m);}if(light.length===p.cells.size){p.build();p.mesh.material=scene.moduleGlowMaterials.get(edge);return p;}const glow=new VoxelPart(title+' · luminous conduits',scene,p.node,p.size);glow.equipmentSlot=slot;for(const c of light){p.cells.delete(c.x+','+c.y+','+c.z);glow.set(c.x,c.y,c.z,c.color);}glow.build();glow.mesh.material=scene.moduleGlowMaterials.get(edge);parts.push(glow);}p.build();return p;};
 const ringZ=(p,x,y,z,r,color,width=.1,depth=.15)=>p.volume([x-r,x+r,y-r,y+r,z-depth/2,z+depth/2],(xx,yy)=>{const d=Math.hypot(xx-x,yy-y);return d<=r&&d>r-width?color:null;});
 const discRing=(p,r,y,color,width=.16)=>p.volume([-r,r,y-.075,y+.075,-r,r],(x,yy,z)=>{const d=Math.hypot(x,z);return d<=r&&d>r-width?color:null;});
 if(slot==='weight'){
  const hull=add(saucer?'lenticular pressure hull':'twin-tail pressure fuselage',[0,0,0],.065);
  if(saucer){const r=5.2;hull.volume([-r,r,-.95,.92,-r,r],(x,y,z)=>{const d=Math.hypot(x,z)/r;if(d>1)return null;const skin=.76*(1-d*d)+.13,inside=Math.abs(y)<skin-.13;return Math.abs(y)<=skin&&!inside?(Math.floor(Math.atan2(z,x)*((bm?20:10)+L))%5===0?metal:body):null;});for(let i=0;i<(bm?20:10+L);i++){const a=i*Math.PI*2/(bm?20:10+L);hull.rod([Math.cos(a)*1.6,.68,Math.sin(a)*1.6],[Math.cos(a)*5,.15,Math.sin(a)*5],.08,edge);}discRing(hull,3.2+L*.04,-.68,metal,.2);}
  else{hull.volume([-1.03,1.03,-.84,.84,-5.4,4.95],(x,y,z)=>{const w=z>2.4?Math.max(.1,(5-z)*.38):z<-2?Math.max(.14,.96+(z+2)*.21):.96,h=z<-2?.75+(z+2)*.13:.77;const cross=bm?Math.abs(x/w)+Math.abs(y/h):(x/w)**2+(y/h)**2;if(cross>1)return null;return Math.abs(y+.18)<.1||Math.floor((z+5.4)*(1+L*.2))%(bm?3:6)===0?edge:y<-.4?metal:body;});for(const side of[-1,1])for(let j=0;j<(bm?12:5+L);j++)hull.box(side*.96,.1,-2+j*.3,.05,.11,.07,metal);}
  finish(hull);
 }
 if(slot==='aero'){
  if(saucer){for(let i=0;i<8;i++){const a=i*Math.PI/4,p=add('radial lifting petal '+i,[0,0,0],.065);p.volume([-6.8,6.8,-.14,.2,-6.8,6.8],(x,y,z)=>{const r=Math.hypot(x,z),angle=Math.atan2(z,x),d=Math.abs(Math.atan2(Math.sin(angle-a),Math.cos(angle-a)));if(r<4.9||r>6.8||d>(bm?.28:.35+L*.008)||Math.abs(y)>.075+L*.012)return null;return r>6.45||d>.28||bm&&r<5.35?edge:body;});for(let j=0;j<(bm?4:L);j++){const r=5.3+j*.28;p.box(Math.cos(a)*r,.19+L*.025,Math.sin(a)*r,.25,.14,.25,hot);}finish(p);}}
  else for(const side of[-1,1]){const p=add('laminar swept wing '+side);p.volume([side<0?-7.7:.9,side<0?-.9:7.7,-.22,.15,-1.5,2.0],(x,y,z)=>{const ax=Math.abs(x),lead=2.0-ax*.13,trail=-.65-ax*.11;if(z>lead||z<trail||Math.abs(y-ax*.011)>.105+L*.008)return null;if(bm&&ax>6&&z<trail+.25)return null;return z>lead-.16||ax>7.15?edge:body;});for(let j=0;j<(bm?3:1+Math.floor(L/2));j++)p.rod([side*(7.6-j*.16),.08,-1],[side*(7.8-j*.16),.45+L*.12,-.25],.07,edge);if(bm)p.rod([side*4.8,.14,.7],[side*6.5,.5,2.0],.09,hot);finish(p);}
 }
 if(slot==='engine'){
  if(saucer){for(let i=0;i<(bm?6:4);i++){const x=(i-((bm?6:4)-1)/2)*1.18,z=-Math.sqrt(4.6**2-x*x),p=add('ion drive chamber '+i,[x,-.05,z]);p.box(0,0,0,.72+L*.055,.62,1.18,body);ringZ(p,0,0,-.65,.31+L*.024,edge,.12,.19);for(let j=0;j<(bm?6:3+L);j++)p.box(0,.36,-.4+j*.15,.78,.12,.05,metal);finish(p);emitters.push([x,-.05,z-.84]);}const core=add('ventral gravitic engine');discRing(core,2.0+L*.04,-.86,edge,.38);for(let i=0;i<12;i++){const a=i*Math.PI/6;core.box(Math.cos(a)*1.7,-.93,Math.sin(a)*1.7,.3,.15,.3,hot);}finish(core);}
  else for(const side of[-1,1]){const cx=side*2.5,r=.57+L*.025,p=add('twin turbine nacelle '+side);p.volume([cx-r,cx+r,-.55,.65,-1.4,3.7],(x,y,z)=>{const d=Math.hypot(x-cx,y-.05);return d<r*(z>3?.87:1)&&(z<3.5||d>r*.6)?(Math.floor(z*7)%8===0?metal:body):null;});for(let z=-1.2;z<3.7;z+=bm?.48:1.1)ringZ(p,cx,.05,z,r+.03,edge,.075,.10);finish(p);const hub=add('coaxial spinner '+side,[cx,.05,3.85],.045);ringZ(hub,0,0,0,.24,edge,.24,.4);finish(hub);surfaces.props.push(hub.node);for(let j=0;j<(bm?10:5+L);j++){const blade=add('swept turbine blade '+side+'/'+j,[0,0,0],.04);blade.node.parent=hub.node;blade.volume([-.13,.22,.2,1.36,-.08,.08],(x,y)=>Math.abs(x-(y-.3)*.07)<.115?(y>1.08?edge:metal):null);blade.node.rotation.z=j*Math.PI*2/(bm?10:5+L);finish(blade);}emitters.push([cx,-.25,-1.6]);if(bm){const booster=add('arc booster '+side);ringZ(booster,cx,-.05,-1.57,.44,hot,.12,.35);finish(booster);}}
 }
 if(slot==='fuel'){
  const count=saucer?(bm?8:4):2;for(let i=0;i<count;i++){const a=saucer?i*Math.PI*2/count:0,x=saucer?Math.cos(a)*3.45:(i?-1:1)*4.45,z=saucer?Math.sin(a)*3.45:-.15,y=saucer?.56:-.4,p=add(saucer?'toroid reservoir '+i:'conformal reserve tank '+i,[x,y,z]);const r=.22+L*.03;p.volume([-r,r,-r,r,-.95,.95],(x,y,z)=>Math.hypot(x,y)<r*Math.sqrt(Math.max(0,1-(z/1.02)**2))?(bm?hot:body):null);for(let j=0;j<(bm?7:3+L);j++)ringZ(p,0,0,-.85+j*1.7/((bm?7:3+L)-1),r+.045,edge,.055,.08);p.box(0,-.2,0,.15,.28,1.1,metal);finish(p);}}
 if(slot==='efficiency'){
  for(const side of[-1,1]){const p=add(saucer?'cryonic lattice '+side:'turbo intercooler '+side,[side*(saucer?2.35:.91),saucer?.66:.35,saucer?-.25:-.3]);for(let j=0;j<(bm?12:4+L);j++){p.box(0,.12,-1+j*2/((bm?12:4+L)-1),saucer?.9:.32,.15+L*.035,.085,j%3?metal:edge);}p.rod([-.15,0,-1.15],[-.15,0,1.15],.075,hot).rod([.15,0,-1.15],[.15,0,1.15],.075,edge);finish(p);}}
 if(slot==='controls'){
  const paddle=(name,origin,w,d,kind,side=0)=>{const p=add(name,origin,.045);p.volume([-w/2,w/2,-.07,.07,-d,0],(x,y,z)=>{if(bm&&z< -d*.6&&Math.floor((x+w/2)/.3)%3===0)return null;return z< -d+.14||Math.abs(x)>w*.4?edge:body;});for(let j=0;j<2+L;j++)p.box(-w*.4+j*w*.8/(1+L),.11,-.12,.07,.13,.2,metal);finish(p);if(kind==='ailerons')surfaces.ailerons.push({node:p.node,side});else surfaces[kind].push(p.node);return p;};
  if(saucer){for(const side of[-1,1]){paddle('roll vane '+side,[side*5.35,.04,-1.65],2.0,.7+L*.05,'ailerons',side);paddle('pitch vane '+side,[side*2.2,.08,-5.0],1.7,.65+L*.07,'elevators');const p=paddle('radial field brake '+side,[side*4.6,.15,2.4],1.25,.7+L*.08,'flaps');p.node.rotation.y=side*.6;const yaw=paddle('yaw vector paddle '+side,[side*4.1,-.25,-3.2],1.1,.65+L*.04,'rudders');yaw.node.rotation.z=Math.PI/2;}}
  else for(const side of[-1,1]){paddle('outboard aileron '+side,[side*5.7,.1,-1.28],3.1,.45+L*.04,'ailerons',side);paddle('Fowler flap '+side,[side*2.1,.01,-.86],2.1,.5+L*.04,'flaps');paddle('tail elevator '+side,[side*1.6,.45,-4.7],2.7,.48+L*.04,'elevators');const p=paddle('split rudder '+side,[side*2.6,1.36,-4.55],1.65,.44+L*.04,'rudders');p.node.rotation.z=Math.PI/2;}
 }
 if(slot==='weapons'&&bm){const count=choice.module.weapon.ammo,perSide=count/2;for(const side of[-1,1]){const x=side*(saucer?4.9:6.0),y=saucer?-.3:-.38,z=saucer?.5:.1,p=add('seeker launch comb '+side,[x,y,z]);const columns=Math.ceil(perSide/2);p.box(0,.15,0,columns*.7,.22,2.5,body);for(let i=0;i<perSide;i++){const xx=(i%columns-(columns-1)/2)*.7,yy=-.22-Math.floor(i/columns)*.68;const round=buildMissile(scene,type,root,[x+xx,y+yy,z]);round.launchIndex=i*2+(side>0?1:0);parts.push(round);p.rod([xx,yy-.05,-1.05],[xx,yy-.05,1.05],.05,edge);}finish(p);}}
 return{root,parts,surfaces,emitters,choice,type};
}
export function createExtraAircraft(scene,type){const saucer=type==='ufo',root=new B.TransformNode('aircraft '+type,scene);root.rotationQuaternion=B.Quaternion.Identity();const parts=[],surfaces={ailerons:[],flaps:[],elevators:[],rudders:[],gear:[],wheels:[],props:[]},baseEmitters=[];
 for(const slot of['weight','aero','engine','fuel','efficiency','controls']){const kit=buildExtraEquipment(scene,type,{slot,level:0,module:null},root);parts.push(...kit.parts);for(const key of Object.keys(kit.surfaces))surfaces[key].push(...kit.surfaces[key]);baseEmitters.push(...kit.emitters);}
 const add=(name,origin=[0,0,0],size=.055,parent=root)=>{const p=new VoxelPart(name,scene,parent,size,origin);parts.push(p);return p;};
 const glass=add('cockpit glass and framing');glass.volume([saucer?-1.5:-.8,saucer?1.5:.8,.55,saucer?1.9:1.75,saucer?-1.4:.7,saucer?2.1:3.5],(x,y,z)=>{const rr=(x/(saucer?1.5:.8))**2+((y-.55)/(saucer?1.35:1.2))**2+((z-(saucer?.35:2.1))/(saucer?1.8:1.5))**2;if(rr>1||rr<.79)return null;return Math.abs(x)<.055||Math.abs(z-(saucer?.35:2.1))<.055?'#344b58':'#71afc3';}).build();
 const cabin=add('seats instruments and cabin fittings');cabin.box(0,.3,saucer?.4:1.9,.72,.25,.65,'#25323c').box(0,.65,saucer?-.0:1.5,.65,.6,.15,'#d3a665').box(0,.65,saucer?1.1:2.6,1.1,.2,.15,'#273f48');for(let i=0;i<6;i++)cabin.box(-.45+i*.18,.73,saucer?1.05:2.55,.12,.07,.06,'#8ff8ef');cabin.build();
 if(!saucer){for(const side of[-1,1]){const tail=add('tail boom and stabilizer '+side);tail.rod([side*2.6,.0,-.8],[side*2.6,.45,-4.5],.17,'#afc3c9').box(side*1.6,.45,-4.2,2.8,.14,1.0,'#d6e2df').box(side*2.6,1.36,-4.1,.16,2.0,.86,'#3e7a9e');for(let j=0;j<7;j++)tail.box(side*.95,.42,-1.8+j*.45,.035,.22,.26,'#557f98');tail.build();}}
 const count=saucer?4:3;for(let i=0;i<count;i++){const a=i*Math.PI/2+Math.PI/4,pos=saucer?[Math.cos(a)*3.5,-.6,Math.sin(a)*3.5]:i===0?[0,-.55,3.15]:[(i===1?-1:1)*1.8,-.55,-1.0],g=add('landing gear '+i,pos,.045);g.rod([0,0,0],[0,-.97,0],.09,'#8eafb9').box(0,-.35,0,.2,.28,.23,'#cfdddd').build();surfaces.gear.push({node:g.node,index:i});if(saucer){const pad=add('landing pad '+i,[0,-1.12,0],.05,g.node);pad.box(0,0,0,.68,.17,.68,'#374a57').box(0,.12,0,.28,.12,.28,'#93e9ee').build();}else{const wheel=add('wheel '+i,[0,-1.12,0],.04,g.node);wheel.volume([-.18,.18,-.37,.37,-.37,.37],(x,y,z)=>Math.hypot(y,z)<.37?(Math.hypot(y,z)<.14?'#a5bac1':'#202d36'):null).build();surfaces.wheels.push(wheel.node);}}
 const detail=add('navigation probes and hull fasteners',[0,0,0],.04);for(let i=0;i<(saucer?32:16);i++){if(saucer){const a=i*Math.PI/16;detail.box(Math.cos(a)*5.05,.26,Math.sin(a)*5.05,.13,.12,.13,i%2?'#5fc6dc':'#d5e4dc');}else for(const side of[-1,1])detail.box(side*.98,-.1,-2.9+i*.38,.06,.06,.05,'#6e8995');}detail.build();
 return{root,parts,surfaces,type,spec:EXTRA_SPECS[type],baseEmitters,voxelCount:parts.reduce((n,p)=>n+p.count,0),partCount:parts.length,dispose(){root.dispose(false,false);}};
}
